<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $bills = \App\Models\GenerateBill::where("bill_no", "15")->get(); foreach ($bills as $bill) { echo "Bill 15 (ID: " . $bill->id . ") for party: " . $bill->party->name . "\n"; foreach ($bill->items as $item) { echo "  Item: ch_no=" . $item->ch_no . ", pcs=" . $item->pcs . "\n"; } }
